@Stable
class CheckoutFormState(
  initialEmail: String,
  private val scope: CoroutineScope,
  val listState: LazyListState
) {
  var email by mutableStateOf(initialEmail)
    private set
  var touched by mutableStateOf(false)
    private set

  // UI logic: how the field LOOKS, not whether the order is valid
  val emailError: String?
    get() = if (touched && !email.contains("@")) "Enter a valid email" else null

  val canSubmit: Boolean get() = emailError == null && email.isNotBlank()

  fun onEmailChange(value: String) {
    email = value
    touched = true
  }

  fun revealFirstError() {
    scope.launch { listState.animateScrollToItem(0) }
  }
}

@Composable
fun rememberCheckoutFormState(initialEmail: String = ""): CheckoutFormState {
  val scope = rememberCoroutineScope()
  val listState = rememberLazyListState()
  return remember(scope, listState) { CheckoutFormState(initialEmail, scope, listState) }
}

