data class CartUiState(val items: List<Item> = emptyList(), val total: Int = 0)

class CartViewModel : ViewModel() {
  private val _state = MutableStateFlow(CartUiState())
  val state: StateFlow<CartUiState> = _state.asStateFlow()

  // ❌ mutates the list behind the value: same instance, equal to itself, no emission
  fun addBroken(item: Item) {
    (_state.value.items as MutableList).add(item)
  }

  // ❌ still broken: copy() of an object holding the same mutated list is equal to it
  fun addAlsoBroken(item: Item) {
    val list = _state.value.items as MutableList
    list.add(item)
    _state.value = _state.value.copy(items = list)
  }

  // ✅ a new list, a new value, and an atomic read-modify-write
  fun add(item: Item) = _state.update {
    it.copy(items = it.items + item, total = it.total + item.price)
  }
}

