NavHost(navController, startDestination = Wizard) {
  // the nested graph is the owner whose lifetime matches the flow
  navigation<Wizard>(startDestination = Step1) {
    composable<Step1> { entry -> StepOne(vm = wizardViewModel(entry, navController)) }
    composable<Step2> { entry -> StepTwo(vm = wizardViewModel(entry, navController)) }
  }
  composable<Confirm> { ConfirmScreen(vm = hiltViewModel()) }
}

@Composable
