// ✅ one owner does the optimistic write, the retry and the rollback
fun toggleFavourite(id: Long) = viewModelScope.launch {
  val before = _state.value.posts.first { it.id == id }.isFavourite
  _state.update { it.setFavourite(id, !before).copy(pending = it.pending + id) }
  runCatching { repo.setFavourite(id, !before) }
    .onFailure { e ->
      _state.update { it.setFavourite(id, before).copy(error = e.message) }  // rollback
    }
  _state.update { it.copy(pending = it.pending - id) }
}

// ❌ read in the composable body: every scrolled pixel recomposes the header
@Composable
fun CollapsingHeader(listState: LazyListState, title: String) {
  val offsetPx = listState.firstVisibleItemScrollOffset
  val offsetDp = with(LocalDensity.current) { -offsetPx.toDp() }
  Box(Modifier.offset(y = offsetDp)) { Text(title) }
}

// ✅ layout-phase read: the lambda runs at layout, composition is skipped entirely
@Composable
fun CollapsingHeaderDeferred(listState: LazyListState, title: String) {
  Box(
    Modifier.offset { IntOffset(x = 0, y = -listState.firstVisibleItemScrollOffset) }
  ) { Text(title) }
}

// ✅ draw-phase read: translation, alpha, scale and rotation belong in graphicsLayer
@Composable
fun FadingHeader(listState: LazyListState, content: @Composable () -> Unit) {
  Box(Modifier.graphicsLayer {
    val px = listState.firstVisibleItemScrollOffset
    translationY = -px.toFloat()
    alpha = (1f - px / 300f).coerceIn(0f, 1f)
  }) { content() }
}

// ❌ the read escaped the lambda — composition-phase invalidation is back
val y = listState.firstVisibleItemScrollOffset
Modifier.offset { IntOffset(0, -y) }

