class EditorViewModel @Inject constructor(
  private val handle: SavedStateHandle,
  repo: NoteRepo
) : ViewModel() {

  private val args = handle.toRoute<Editor>()          // nav argument, restored for free

  // observable saved entry — survives rotation AND process death
  val draft: StateFlow<String> = handle.getStateFlow(KEY_DRAFT, "")
  fun onDraftChange(value: String) { handle[KEY_DRAFT] = value }

  // the Compose-state form of the same storage
  var selectedTab by handle.saveable { mutableIntStateOf(0) }
    private set

  // NOT saved: reload it instead of stuffing a page of rows into the Bundle
  val note: StateFlow<Note?> = repo.note(args.id)
    .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), null)

  private companion object { const val KEY_DRAFT = "draft" }
}

